package com.kai.automusic;
import android.media.*;
public final class DjSampler {
 private static final java.util.concurrent.ExecutorService worker=java.util.concurrent.Executors.newSingleThreadExecutor();
 private static volatile AudioTrack active;
 public static void play(int id){worker.execute(()->{try{if(active!=null){active.release();active=null;}int rate=22050,n=(int)(rate*(id==3||id==8?1.1:.45));short[] pcm=new short[n];java.util.Random rnd=new java.util.Random();double phase=0;for(int i=0;i<n;i++){double t=i/(double)rate,x=i/(double)n,f=440,env=Math.min(1,t/.008)*Math.pow(1-x,1.5),s=0;switch(id){case 0:f=330;s=.65*Math.sin(phase)+.25*Math.sin(phase*2)+.1*Math.sin(phase*3);break;case 1:f=1800*(1-x)+90;s=Math.sin(phase);break;case 2:s=(rnd.nextDouble()*2-1)*Math.exp(-t*18);break;case 3:f=100+1800*x;s=Math.sin(phase)*x;break;case 4:f=700*Math.exp(-t*8)+45;s=Math.sin(phase);break;case 5:f=150*Math.exp(-t*20)+40;s=Math.sin(phase)*Math.exp(-t*8);break;case 6:f=880;s=Math.sin(phase);break;case 7:s=(rnd.nextDouble()*2-1)*Math.exp(-t*12)+.2*Math.sin(phase);f=180;break;case 8:f=200+1000*x;s=.5*Math.sin(phase)+.5*(rnd.nextDouble()*2-1);break;default:int v=id-9;f=(110+v*47)*(1+(v%5-2)*x*.35);s=(.7*Math.sin(phase)+.2*Math.sin(phase*(2+v%3))+.1*(rnd.nextDouble()*2-1)*(v%4))* (v%3==0?Math.pow(Math.abs(Math.sin(t*35)),2):1);}phase+=2*Math.PI*f/rate;pcm[i]=(short)(Math.max(-1,Math.min(1,s*env))*6500);}AudioTrack a=new AudioTrack(AudioManager.STREAM_MUSIC,rate,AudioFormat.CHANNEL_OUT_MONO,AudioFormat.ENCODING_PCM_16BIT,n*2,AudioTrack.MODE_STATIC);a.write(pcm,0,n);active=a;a.play();}catch(Exception ignored){}});}
}